async () => {
  const r = await fetch('/collections/urban-low-height/sku-profile.json', { cache: 'force-cache' });
  const h = {}; r.headers.forEach((v, k) => (h[k] = v));
  const regs = navigator.serviceWorker ? (await navigator.serviceWorker.getRegistrations()).map((x) => x.scope) : 'n/a';
  const nav = performance.getEntriesByType('resource').filter((e) => /sku-profile\.json/.test(e.name)).map((e) => ({ transferSize: e.transferSize, encodedBodySize: e.encodedBodySize, decodedBodySize: e.decodedBodySize, deliveryType: e.deliveryType, responseStatus: e.responseStatus }));
  return { cachedHeaders: h, serviceWorkers: regs, resourceTiming: nav };
}
